import numpy as np
from numpy.lib.mixins import NDArrayOperatorsMixin
class MyArray(NDArrayOperatorsMixin):
    def __init__(self, data):
        self.data = np.array(data)
    def __array_ufunc__(self, ufunc, method, *inputs, **kwargs):
        if method == '__call__':
            scalars = [i.data if isinstance(i, MyArray) else i for i in inputs]
            return MyArray(ufunc(*scalars, **kwargs))
        return NotImplemented
    def __repr__(self):
        return f'MyArray({self.data})'

a = MyArray([1, 2])
b = MyArray([3, 4])
print(a + b)
